def key_match_paged(key0: list[int], key1: list[int], page_size: int) -> int:
    """Return the shared prefix length, rounded down to whole pages.

    This mirrors the non-bigram RadixKey matching behavior used by RadixCache:
    only complete pages of matching leading tokens are counted.
    """
    if page_size < 1:
        raise ValueError("page_size must be >= 1")

    matched = 0
    for token0, token1 in zip(key0, key1):
        if token0 != token1:
            break
        matched += 1

    return (matched // page_size) * page_size


def test_matches_only_complete_pages():
    assert key_match_paged([1, 2, 3, 4, 5, 6], [1, 2, 3, 4, 9, 6], 2) == 4


def test_partial_trailing_page_is_ignored():
    # Four tokens match, but with page_size=3 only the first full page counts.
    assert key_match_paged([1, 2, 3, 4, 5], [1, 2, 3, 4, 9], 3) == 3


def test_page_size_one_counts_every_matching_token():
    assert key_match_paged([1, 2, 3, 9], [1, 2, 3, 4], 1) == 3


def test_shorter_key_limits_match_and_is_page_aligned():
    assert key_match_paged([1, 2, 3], [1, 2, 3, 4], 1) == 3
    assert key_match_paged([1, 2, 3], [1, 2, 3, 4], 2) == 2


def test_empty_or_fully_mismatched_keys_return_zero():
    assert key_match_paged([], [], 4) == 0
    assert key_match_paged([], [1, 2, 3, 4], 2) == 0
    assert key_match_paged([1, 2], [9, 8], 2) == 0


def test_invalid_page_size_raises():
    with pytest.raises(ValueError):
        key_match_paged([1], [1], 0)
